/** Parses `git diff --numstat -M` output, keyed by the file's new/current path. */
function parseNumstat(output: string): Map<string, NumstatEntry> {
  const map = new Map<string, NumstatEntry>();
  for (const line of output.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const [insRaw, delRaw, pathField] = trimmed.split("\t");
    // Binary files report "-" instead of a count.
    const insertions = insRaw === "-" ? 0 : Number(insRaw);
    const deletions = delRaw === "-" ? 0 : Number(delRaw);
    const newPath = pathField.includes(" => ") ? pathField.split(" => ")[1] : pathField;
    map.set(newPath, { insertions, deletions });
  }
  return map;
}

tool_input.new_string:
/**
 * Expands a `--numstat` path field to its new-side path. Git renders a
 * rename two different ways depending on whether old/new share a common
 * prefix/suffix: a plain "old/path => new/path" for renames with nothing in
 * common, or a compact "common/{old => new}/tail" brace form when they share
 * one — this is purely a numstat/diff-text rendering choice, independent of
 * the actual rename detection. The brace form was previously unhandled: a
 * naive split on " => " left the trailing "}" attached and dropped the
 * shared prefix, so the resulting key never matched the file's real new path
 * from --name-status, and the rename silently lost its insertion/deletion
 * counts (recorded as +0/-0 and then filtered out as "below the minimum").
 */
function expandNumstatNewPath(pathField: string): string {
  const braceMatch = pathField.match(/^(.*)\{(.*) => (.*)\}(.*)$/);
  if (braceMatch) {
    const [, prefix, , newPart, suffix] = braceMatch;
    return `${prefix}${newPart}${suffix}`;
  }
  if (pathField.includes(" => ")) {
    return pathField.split(" => ")[1];
  }
  return pathField;
}

/** Parses `git diff --numstat -M` output, keyed by the file's new/current path. */
function parseNumstat(output: string): Map<string, NumstatEntry> {
  const map = new Map<string, NumstatEntry>();
  for (const line of output.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const [insRaw, delRaw, pathField] = trimmed.split("\t");
    // Binary files report "-" instead of a count.
    const insertions = insRaw === "-" ? 0 : Number(insRaw);
    const deletions = delRaw === "-" ? 0 : Number(delRaw);
    const newPath = expandNumstatNewPath(pathField);
    map.set(newPath, { insertions, deletions });
  }
  return map;
}
